//#region src/server/multi-stage.ts
/**
* The origin a shared cache identity names in place of the request's. Next.js
* keys its response cache by pathname, so one stored response answers every
* host an app serves. `.invalid` never resolves, so no configured domain or
* host condition can match it when the identity is replayed.
*/
const VINEXT_CACHE_IDENTITY_ORIGIN = "https://cache-identity.vinext.invalid";
/** Name `origin` in place of a dispatch URL's origin in a shared cache identity. */
function withCacheIdentityOrigin(requestUrl, origin = VINEXT_CACHE_IDENTITY_ORIGIN) {
	const url = new URL(requestUrl);
	return `${origin}${url.pathname}${url.search}`;
}
/** Whether a response-stage cache must reject a field it did not key itself by. */
function hasUnsupportedResponseStageVary(headers, keyedRequestHeaders = []) {
	const keyedFields = new Set([...keyedRequestHeaders].map((name) => name.trim().toLowerCase()).filter(Boolean));
	return (headers.get("Vary") ?? "").split(",").map((name) => name.trim().toLowerCase()).filter(Boolean).some((name) => name === "*" || !keyedFields.has(name));
}
//#endregion
export { VINEXT_CACHE_IDENTITY_ORIGIN, hasUnsupportedResponseStageVary, withCacheIdentityOrigin };
